L000294	\section{End Matter}
L000295	\subsection{Renormalized BKT transition temperature}
L000296	The renormalized BKT transition temperature reads
L000297	\begin{equation}
L000298	    \beta_{\rm{eff}}=\beta\left(1-\frac{\pi g}{2-\sigma-\eta}\right).
L000299	\end{equation}
L000300	The BKT transition appears for the critical temperature $\beta_{\rm{eff}, c}=2/\pi$. This condition can be solved analytically, and as a result we obtain for the critical temperature $T_{{\mathrm{BKT}}}=1/\beta_c$:
L000301	\begin{equation}
L000302	    T_{\mathrm{BKT}}= \frac{\pi}{4}\left(9-4\sigma +\sqrt{49+16\pi g-56\sigma +16\sigma^2}\right).
L000303	\end{equation}
L000304	\subsection{Critical temperature of long-range interactions}
L000305	Long-range interactions become relevant when
L000306	\begin{equation}
L000307	    \sigma<2-\eta.
L000308	\end{equation}
L000309	Recalling that $\eta=T/2\pi$, we can solve for the temperature, and we obtain
L000310	\begin{equation}
L000311	    T_{\mathrm{c, lr}}=2\pi(2-\sigma).
L000312	\end{equation}
L000313	\subsection{Remaining Integral in the LP argument}\label{sec:app_lp_integral}
L000314	After integrating out spin waves, we are left with evaluating the following integral over a vortex-antivortex configuration
L000315	\begin{equation}\label{eq:endmatter_integral}
L000316	    I\left(r\right)=\!\!\!\int\displaylimits_{1<|\bm{x}-\bm{y}|}\!\!\!\!\!\frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{2+\sigma+\eta}}\left[1\!-\!\cos{\big(\theta(x)\!-\!\theta(y)\big)}\right].
L000317	\end{equation}
L000318	Here, $\theta(\bm{x})$ describes the field of a vortex-antivortex configuration with separation $r$ between the vortex and antivortex. All distances are measured in units of the lattice spacing $a$. To evaluate the integral, we split it into two regions:
L000319	\begin{equation}\label{eq:endmatter_integralsplit}
L000320	    \begin{split}
L000321	        I\left(r\right)=&\!\!\!\int\displaylimits_{1<|\bm{x}-\bm{y}|<r}  \!\!\!\!\!\frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{2+\sigma+\eta}}\left[1\!-\!\cos{\big(\theta(\bm{x})\!-\!\theta(\bm{y})\big)}\right]\\
L000322	        +&\!\!\!\int\displaylimits_{r<|\bm{x}-\bm{y}|} \!\!\!\!\! \frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{2+\sigma+\eta}}\left[1\!-\!\cos{\big(\theta(\bm{x})\!-\!\theta(\bm{y})\big)}\right].
L000323	    \end{split}
L000324	\end{equation}
L000325	We are going to evaluate both summands separately. We start with the first summand. Here, we have restricted $1<|\bm{x}-\bm{y}|<r$. In this regime, the field $\theta$ is smooth enough to expand the cosine to second order. We obtain
L000326	\begin{equation}
L000327	\begin{split}
L000328	    &\int\displaylimits_{1<|\bm{x}-\bm{y}|<r}   \!\!\!\!\!\frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{2+\sigma+\eta}}\left[1-\cos{\big(\theta(\bm{x})-\theta(\bm{y})\big)}\right]\\
L000329	    =&\frac{1}{2}\!\!\!\!\!\int\displaylimits_{1<|\bm{x}-\bm{y}|<r} \!\!\!\!\!\frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{2+\sigma+\eta}}\left((\bm{x}-\bm{y})\cdot \bm{\nabla}\theta(\bm{x})\right)^2\\
L000330	    =&\frac{1}{2}\int \dd[2]\bm{x}\left(\bm{\nabla}\theta(\bm{x})\right)^2\!\!\!\int \displaylimits_{1<|\bm{q}|<r} \!\!\!\frac{\dd[2]\bm{q}}{|\bm{q}|^{\sigma+\eta}}\cos{(\alpha)}^2 \\
L000331	    =&\frac{\pi}{2(2-\sigma-\eta)}\left(r^{2-\sigma-\eta}-1\right)\int \dd[2]\bm{x} \left(\nabla\theta(\bm{x})\right)^2 \\
L000332	    =&\frac{2\pi^2}{2-\sigma-\eta}\left(r^{2-\sigma-\eta}-1\right)\ln{\left(r\right)}.
L000333	\end{split}
L000334	\end{equation}
L000335	Here, we used that:
L000336	\begin{equation}
L000337	    \int d^2x \left(\nabla\theta(x)\right)^2=4\pi\ln{\left( r\right)}.
L000338	\end{equation}
L000339	The expansion of the cosine for $|\bm{x}-\bm{y}|<r$ is an apparent approximation. Nevertheless, the argument as to why this is allowed is similar to the short-range XY model: On distances smaller than the scale $r$, the vortex field configuration in the system is smooth, so that the cosine can be approximated by the quadratic expansion. Also, note that the exact length $r$ where we split the integral does not matter: we could have chosen $1<|x-y|<r/m$ with $m>1$, and the calculation is similar. This would reduce the error of this approximation, at the cost of introducing the new length scale $r/m$.
L000340	
L000341	Next, we consider the second summand of Eq.~\eqref{eq:endmatter_integralsplit}. Here, we can simply rescale $\bm{x}$ and $\bm{y}$ by $r$ to obtain
L000342	\begin{equation}
L000343	    \int\displaylimits_{r<|\bm{x}-\bm{y}|<L}  \!\!\!\!\!\!\!\!\frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{2+\sigma+\eta}}\left[1\!-\!\cos{\big(\theta(\bm{x})\!-\!\theta(\bm{y})\big)}\right]=k\cdot r^{2-\sigma-\eta}.
L000344	\end{equation}
L000345	Here, $k$ is a positive, $r$-independent constant. Combining these results, we have
L000346	\begin{equation}\label{eq:lrxy_lp_theintegralfullsolution}
L000347	\begin{split}
L000348	    I(r)=&J\left(r\right)\cdot r^{2-\sigma-\eta}-\frac{2\pi^2}{2-\sigma-\eta}\cdot \ln{\left(r\right)}.
L000349	\end{split}
L000350	\end{equation}
L000351	Here, we have defined
L000352	\begin{equation}\label{eq:lrxy_lp_thejfunction}
L000353	    J\left(r\right)=\frac{2\pi^2}{2-\sigma-\eta}\ln{\left(r\right)}+k,
L000354	\end{equation}
L000355	which only has a weak $r$-dependence proportional to $\ln{\left(r\right)}$. Since $J(r)$ is multiplied with a polynomial in $r$, this $r$ dependence does not determine the asymptotic behavior of $I(r)$ and can be neglected.
L000356	
L000357	\subsection{RG flow equations}
L000358	We derive the RG equations of the long-range XY model by utilizing the method of spin wave renormalization \cite{Chaikin_Lubensky_1995}. The advantage of this method is that it does not rely on duality mappings, which we know are not applicable in the long-range XY model \cite{Giachetti2023Villain}. To start, we impose an external gradient on the field $\phi(\bm{x})$ as follows:
L000359	\begin{equation}
L000360	    \phi(\bm{x})=\Tilde{\phi}(\bm{x})+\bm{w}\cdot \bm{x}.
L000361	\end{equation}
L000362	We define the macroscopic renormalized temperature as the curvature of the free energy with respect to $\bm{w}$ as
L000363	\begin{equation}\label{eq:endmatter_rencon}
L000364	    \frac{1}{2}L^2\beta_R \bm{w}^2=\beta F(\bm{w})-\beta F(\bm{0}).
L000365	\end{equation}
L000366	The free energy is defined as
L000367	\begin{equation}\label{eq:endmatter_freeenergy}
L000368	    \beta F(\bm{w})=-\ln{\left\{\int D[\varphi]\sum\displaylimits_{n_{\bm{r}}}\exp\left[-\beta H(\bm{w})\right] \right\}}.
L000369	\end{equation}
L000370	Here, $H(\bm{w})$ is the Hamiltonian of the long-range XY model from Eq.~\eqref{eq:hamil_writtenas_srandlr} including the field gradient $\bm{w}$. We define the spin wave and vortex averages as
L000371	\begin{align}
L000372	    \langle O[\varphi]\rangle_{\mathrm{sw}}=&\frac{1}{Z_{\mathrm{sw}}}\int D[\varphi]e^{-\frac{\beta}{2}\int \dd \bm{x}(\bm{\nabla}\varphi(\bm{x})^2}O[\varphi]\\
L000373	    \langle O[n_{\bm{r}}]\rangle_{v}=&\frac{1}{Z_{v}}\sum \displaylimits_{n_{\bm{r}}}y^{N}e^{-\beta\pi\sum_{\bm{x}, \bm{y}}n_{\bm{x}}n_{\bm{y}}G(\bm{x}-\bm{y})}O[n_{\bm{r}}],
L000374	\end{align}
L000375	where $N=\sum_{\bm{r}}n_{\bm{r}}^2$ is the sum over squared charges of vortices. $Z_{\mathrm{sw}}$ and $Z_v$ are defined by $\langle 1\rangle_{\mathrm{sw}}=\langle 1\rangle_v=1$.
L000376	
L000377	Using this, the free energy Eq.~\eqref{eq:endmatter_freeenergy} becomes
L000378	\begin{widetext}
L000379	    \begin{equation}
L000380	    \beta F(\bm{w})=\ln{\left\{\left\langle e^{-\beta \int \dd[2]\bm{r} \hspace{1mm}\bm{w}\cdot \bm{\nabla}\theta(\bm{x})}e^{-\beta g\int\frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{2+\sigma}}\left[1-\cos{(\varphi(\bm{x})-\varphi(\bm{y})+\theta(\bm{x})-\theta(\bm{y})+\bm{w}\cdot (\bm{x}-\bm{y}))}\right]}\right\rangle_{v, sw}Z_{\mathrm{sw}}Z_v\right\}}.
L000381	\end{equation}
L000382	\end{widetext}
L000383	We recall that
L000384	\begin{equation}
L000385	    \theta(\bm{x})=\sum_{\bm{r}}n_{\bm{r}}\cdot \arg((x_1-r_1)+i(x_2-r_2)),
L000386	\end{equation}
L000387	where $\arg(c)$ is the complex argument function which gives the polar phase of the complex number $c$. Here and in the following we measure distances in units of the lattice spacing $a$, effectively setting $a=1$.
L000388	To make analytical progress, we need to expand the free energy to linear order in $g$. Further, we are only interested in $F(\bm{w})$ to second order in $\bm{w}$, so we can also expand in $\bm{w}$. Due to the isotropy of the system, the first order in $\bm{w}$ vanishes and the second order only depends on $\bm{w}^2$.
L000389	When only keeping the relevant terms, we obtain the following equation for $\beta_R$:
L000390	\begin{widetext}
L000391	    \begin{equation}\label{eq:endmatter_betarlong}
L000392	    \begin{split}
L000393	        \beta_R=&\beta -\frac{\beta^2}{2L^2}\int \dd[2]\bm{r}\dd[2]\bm{r}'\big\langle \bm{\nabla}\theta(\bm{r})\cdot \bm{\nabla}\theta(\bm{r}')\big\rangle_v\left[1-\beta g\int \frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{2+\sigma}}\langle \cos{(\varphi(\bm{x})-\varphi(\bm{y})}\rangle_{\mathrm{sw}} \right]\\
L000394	        &+\frac{\beta g}{2L^2}\int \frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{\sigma}}\langle \cos{(\varphi(\bm{x})-\varphi(\bm{y})}\rangle_{\mathrm{sw}}\left\langle\cos{(\theta(\bm{x})-\theta(\bm{y}))}\left[1-\frac{\beta^2}{|\bm{x}-\bm{y}|^2}\int \dd[2]\bm{r}\dd[2]\bm{r}'\bm{\nabla}\theta(\bm{r})\cdot \bm{\nabla}\theta(\bm{r}')\right]\right\rangle_v\\
L000395	        &-\frac{\beta^2 g}{L^2}\int \frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{2+\sigma}}\langle \cos{(\varphi(\bm{x})-\varphi(\bm{y})}\rangle_{\mathrm{sw}}\int\dd[2]\bm{r}(\bm{x}-\bm{y})\cdot\langle\bm{\nabla}\theta(\bm{r}) \sin{(\theta(\bm{x})-\theta(\bm{y}))}\rangle_v
L000396	    \end{split}
L000397	    \end{equation}
L000398	\end{widetext}
L000399	We recall that $\langle\cos{(\varphi(\bm{x})-\varphi(\bm{y}))}\rangle_{\mathrm{sw}}=1/|\bm{x}-\bm{y}|^{\eta}$. Further, the expectation value over vortices can be calculated perturbatively in $y$. We define $\langle O\rangle_N$ as the expectation value of the operator $O$ with respect to vortices including all terms to order $y^N$, and correspondingly we define $Z_N$. Then, for operators $O$ that vanish when no vortices are present, we have that
L000400	\begin{equation}
L000401	    \langle O\rangle_2=y^2\int\frac{\dd[2]\bm{r}_1\dd[2]\bm{r}_2}{|\bm{r}_1-\bm{r}_2|^{2\pi\beta}}O(\bm{r}_1, \bm{r}_2).
L000402	\end{equation}
L000403	Here, $\bm{r}_1$ is the location of the vortex and $\bm{r}_2$ the location of the antivortex. Using this, we can transform Eq.~\eqref{eq:endmatter_betarlong} into a more tractable form. While doing so, integrals of the following form appear:
L000404	\begin{equation}
L000405	    \int \frac{\dd[2]\bm{x}\dd[2]\bm{y}}{|\bm{x}-\bm{y}|^{u}}\int \frac{\dd[2]\bm{r}_1\dd[2]\bm{r}_2}{|\bm{r}_1-\bm{r}_2|^{u}}(...).
L000406	\end{equation}
L000407	To solve those integrals, we split the integration domain into the regions $|\bm{x}-\bm{y}|<|\bm{r}_1-\bm{r}_2|$ and $|\bm{x}-\bm{y}|>|\bm{r}_1-\bm{r}_2|$. To solve the integrals in both regions, we note that the vortex phase $\theta$ fulfills a neat duality condition. Denoting by $\theta(\bm{x}, \bm{r}_1)$ the field at position $\bm{x}$ caused by a vortex at position $\bm{r}_1$, we have that $\theta(\bm{x}, \bm{r}_1)=\theta(\bm{r}_1, \bm{x})+\pi$. Therefore, the difference of vortex phases which appear in Eq.~\eqref{eq:endmatter_betarlong} have the following property:
L000408	
L000409	
L000410	
L000411	
L000412	
L000413	\begin{multline}
L000414	    \theta(\bm{x})-\theta(\bm{y})
L000415	    =\theta(\bm{x}, \bm{r}_1)-\theta(\bm{x}, \bm{r}_2)-\theta(\bm{y}, \bm{r}_1)+\theta(\bm{y}, \bm{r}_2) \\
L000416	    =(\theta(\bm{r}_1, \bm{x})-\theta(\bm{r}_1, \bm{y}))-(\theta(\bm{r}_2, \bm{x})-\theta(\bm{r}_2, \bm{y})).
L000417	\end{multline}
L000418	Using this, the appearing integrals in Eq.~\eqref{eq:endmatter_betarlong} can be solved analogously to the integral in Eq.~\eqref{eq:endmatter_integral}. Further, we use that
L000419	\begin{equation}
L000420	    1+\alpha \ln{(r)}=r^{\alpha}+\mathcal{O}(\alpha^2).
L000421	\end{equation}
L000422	Then, introducing back the lattice spacing $a$, Eq.~\eqref{eq:endmatter_betarlong} becomes
L000423	\begin{widetext}
L000424	    \begin{equation}\label{eq:endmatteer_betafinal}
L000425	    \begin{split}
L000426	        \beta_R=&\beta-\pi^3\beta^2y^2e^{-\frac{2\pi g}{2-\sigma-\eta}}\int_a^{\infty}\frac{\dd{r}}{a}\left(\frac{r}{a}\right)^{3-2\pi\beta\left(1-\frac{\pi g}{2-\sigma-\eta}\right)}+\pi \beta ge^{\frac{2\pi^3\beta y^2}{4-2\pi\beta}}\int \displaylimits_{a}^{\infty}\frac{\dd{r}}{a} \left(\frac{r}{a}\right)^{1-\sigma-\eta+\frac{2\pi^2y^2}{4-2\pi\beta}}\\
L000427	        &+\beta g y^2\pi^3\int \displaylimits_a^{\infty}\frac{\dd{r}}{a}\left(\frac{r}{a}\right)^{5-\sigma-\eta-2\pi\beta}\left(\frac{-2\beta \pi}{2-\sigma-\eta}+\frac{-2\beta\pi}{4-2\pi\beta}+\ln{\left(\frac{r}{a}\right)}\left(\frac{2\beta^2\pi^2}{2-\sigma-\eta}-\frac{2}{4-2\pi\beta}\right)\right).
L000428	    \end{split}
L000429	    \end{equation}
L000430	\end{widetext}
L000431	All integrals in Eq.~\eqref{eq:endmatteer_betafinal} come with the lattice spacing as their lower cutoff. We renormalize the theory by introducing a second scale, which is slightly larger than the lattice spacing $a\rightarrow a'>a$ and introducing new variables $\beta', g', y'$, while keeping the macroscopic $\beta_R$ fixed.  In the case of an infinitesimal change $a'=ae^{dl}$ with $dl\ll1$ this leads to the differential renormalization group equations:
L000432	\begin{equation}
L000433	    \begin{split}
L000434	        \frac{\partial\beta}{\partial l}\!=&\!-\pi^3\beta^2y^2\!+\!\pi \beta g\!-\!\gamma \beta g y^2\pi^3\!\left(\!\frac{2\beta \pi}{2-\sigma-\eta}\!+\!\frac{2\beta\pi}{4-2\pi\beta}\!\right)\\
L000435	        \frac{\partial y^2}{\partial l}\!=&\!\left(4-2\pi\beta\left(1-\frac{\pi g}{2-\sigma-\eta}\right)\right)y^2\\
L000436	        \frac{\partial g}{\partial l}\!=&\!\left(2-\sigma-\eta+\frac{2\pi^2y^2}{4-2\pi \beta}-\pi^3\beta y^2\right)g\\
L000437	        \frac{\partial \gamma}{\partial l}\!=&\!-\frac{\beta^2\pi^2(4-2\pi\beta)-(2-\sigma-\eta)}{\beta \pi(6-2\pi\beta-\sigma-\eta)}.
L000438	    \end{split}
L000439	\end{equation}
L000440	The additional coupling $\gamma$ is generated under the RG flow. The appearance can be understood by the fact that out of the RG procedure we obtain four equations (one for $\beta$, $y^2$, $g$ and $gy^2$), but we only have three couplings to renormalize, so the system is overdetermined. We do not have a physical interpretation of $\gamma$, and henceforth set $\gamma=0$ in the analysis of the equations. The analysis of the full RG equations including $\gamma$ is left open for future work.
